import "server-only";
import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as AuthUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // WorkOS user id, set once the user has signed in at least once.
  authId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Links a WorkOS identity to a Notely user: matched by WorkOS id first, then by
// email (so seeded users keep their record), otherwise a new user is created.
export async function upsertUserFromAuth(authUser: AuthUser): Promise<User> {
  const email = authUser.email.toLowerCase();
  const name =
    [authUser.firstName, authUser.lastName].filter(Boolean).join(" ") || email.split("@")[0];

  const existing =
    users.find((u) => u.authId === authUser.id) ??
    users.find((u) => !u.authId && u.email.toLowerCase() === email);

  if (existing) {
    existing.authId = authUser.id;
    existing.email = email;
    return existing;
  }

  const user: User = {
    id: String(users.length + 1),
    email,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
    authId: authUser.id,
  };
  users.push(user);
  return user;
}

// Returns the signed-in user, or undefined for signed-out visitors.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  return user ? upsertUserFromAuth(user) : undefined;
}

// Like getCurrentUser, but redirects signed-out visitors to sign in.
export async function requireUser(): Promise<User> {
  const { user } = await withAuth({ ensureSignedIn: true });
  return upsertUserFromAuth(user);
}
